def normal_form(word):
    pending = [(word, 1)]
    result = {}
    while pending:
        w, coefficient = pending.pop()
        k = 0
        while k + 1 < len(w):
            a, x = w[k]
            b, y = w[k + 1]
            if a == b and x == y:
                break
            if a < b or (a == b and x > y):
                swapped = w[:k] + (w[k + 1], w[k]) + w[k + 2:]
                pending.append((swapped, -coefficient))
                if a == 0 and b == 1 and x == y:
                    pending.append((w[:k] + w[k + 2:], coefficient))
                break
            k += 1
        if k + 1 >= len(w):
            result[w] = result.get(w, 0) + coefficient
    return {w: c for w, c in result.items() if c}


def compile_product(word, diagonal):
    polynomial = normal_form(word)
    if not diagonal:
        for w, coefficient in tuple(polynomial.items()):
            creators = tuple((0, mode) for flag, mode in w if flag == 1)
            annihilators = tuple((1, mode) for flag, mode in w if flag == 0)
            r = len(creators)
            s = len(annihilators)
            parity = ((r * (r - 1) + s * (s - 1)) // 2) % 2
            if parity:
                coefficient = -coefficient
            adjoint = annihilators + creators
            polynomial[adjoint] = polynomial.get(adjoint, 0) + coefficient
    return tuple((w, c) for w, c in polynomial.items() if c)


