def symmetric_template(left, right):
    sequence = tuple((1 - flag, mode) for flag, mode in reversed(left)) + right
    states = {((), ()): 1}
    for flag, mode in sequence:
        following = {}
        for groups, coefficient in states.items():
            creation, annihilation = groups
            if flag == 0:
                if mode not in annihilation:
                    position = sum(1 for value in annihilation if value < mode)
                    value = coefficient
                    if (len(annihilation) - position) % 2:
                        value = -value
                    key = (creation, annihilation[:position] + (mode,) + annihilation[position:])
                    following[key] = following.get(key, 0) + value
            else:
                if mode in annihilation:
                    position = annihilation.index(mode)
                    value = coefficient
                    if (len(annihilation) - 1 - position) % 2:
                        value = -value
                    key = (creation, annihilation[:position] + annihilation[position + 1:])
                    following[key] = following.get(key, 0) + value
                if mode not in creation:
                    position = sum(1 for value in creation if value < mode)
                    value = coefficient
                    if (len(annihilation) + len(creation) - position) % 2:
                        value = -value
                    key = (creation[:position] + (mode,) + creation[position:], annihilation)
                    following[key] = following.get(key, 0) + value
        states = {key: value for key, value in following.items() if value != 0}
        if not states:
            break
    orbits = {}
    for groups, coefficient in states.items():
        creation, annihilation = groups
        if creation > annihilation:
            creation, annihilation = annihilation, creation
        key = (creation, annihilation)
        orbits[key] = orbits.get(key, 0) + coefficient
    result = []
    for groups, coefficient in orbits.items():
        if coefficient != 0:
            creation, annihilation = groups
            word = tuple((1, mode) for mode in creation) + tuple((0, mode) for mode in annihilation)
            if creation == annihilation:
                result.append((word, 2 * coefficient))
            else:
                result.append((word, coefficient))
                transpose = tuple((1, mode) for mode in annihilation) + tuple((0, mode) for mode in creation)
                result.append((transpose, coefficient))
    return tuple(result)


def propose(payload):
    words = payload['words']
    cache = payload['cache']
    result = {}
    for i in range(len(words)):
        first = words[i]
        for j in range(i, len(words)):
            second = words[j]
            modes = sorted(set(mode for flag, mode in first + second))
            labels = {mode: rank for rank, mode in enumerate(modes)}
            left = tuple((flag, labels[mode]) for flag, mode in first)
            right = tuple((flag, labels[mode]) for flag, mode in second)
            if left > right:
                left, right = right, left
            key = ('symmetric_order_orbits_v1', left, right)
            if key not in cache:
                cache[key] = symmetric_template(left, right)
            coordinate = (i, j)
            for template, coefficient in cache[key]:
                if i == j:
                    coefficient = coefficient // 2
                if coefficient != 0:
                    word = tuple((flag, modes[label]) for flag, label in template)
                    result.setdefault(word, {})[coordinate] = coefficient
    return result

def normal_pattern(word, memo):
    if word in memo:
        return memo[word]
    for position in range(len(word) - 1):
        left_flag, left_mode = word[position]
        right_flag, right_mode = word[position + 1]
        if left_flag == right_flag and left_mode == right_mode:
            memo[word] = {}
            return memo[word]
        inversion = left_flag < right_flag or (left_flag == right_flag and left_mode > right_mode)
        if inversion:
            swapped = word[:position] + (word[position + 1], word[position]) + word[position + 2:]
            result = {}
            for term, coefficient in normal_pattern(swapped, memo).items():
                result[term] = -coefficient
            if left_flag == 0 and right_flag == 1 and left_mode == right_mode:
                contracted = word[:position] + word[position + 2:]
                for term, coefficient in normal_pattern(contracted, memo).items():
                    result[term] = result.get(term, 0) + coefficient
            result = {term: coefficient for term, coefficient in result.items() if coefficient}
            memo[word] = result
            return result
    result = {word: 1}
    memo[word] = result
    return result


def emission_template(pattern, symmetric, memo):
    polynomial = normal_pattern(pattern, memo)
    if not symmetric:
        return tuple(polynomial.items())
    result = polynomial.copy()
    for word, coefficient in polynomial.items():
        creators = 0
        while creators < len(word) and word[creators][0] == 1:
            creators += 1
        annihilators = len(word) - creators
        swaps = (creators * (creators - 1) + annihilators * (annihilators - 1)) // 2
        adjoint = tuple((1, mode) for flag, mode in word[creators:]) + tuple((0, mode) for flag, mode in word[:creators])
        if swaps % 2:
            coefficient = -coefficient
        result[adjoint] = result.get(adjoint, 0) + coefficient
    return tuple((word, coefficient) for word, coefficient in result.items() if coefficient)


