def normalform(word):
    states = {((), ()): 1}
    for flag, mode in word:
        following = {}
        for groups, coefficient in states.items():
            creation, annihilation = groups
            if flag == 0:
                if mode not in annihilation:
                    position = sum(1 for value in annihilation if value < mode)
                    value = coefficient
                    if (len(annihilation) - position) % 2:
                        value = -value
                    key = (creation, annihilation[:position] + (mode,) + annihilation[position:])
                    following[key] = following.get(key, 0) + value
            else:
                if mode in annihilation:
                    position = annihilation.index(mode)
                    value = coefficient
                    if (len(annihilation) - 1 - position) % 2:
                        value = -value
                    key = (creation, annihilation[:position] + annihilation[position + 1:])
                    following[key] = following.get(key, 0) + value
                if mode not in creation:
                    position = sum(1 for value in creation if value < mode)
                    value = coefficient
                    if (len(annihilation) + len(creation) - position) % 2:
                        value = -value
                    key = (creation[:position] + (mode,) + creation[position:], annihilation)
                    following[key] = following.get(key, 0) + value
        states = {key: value for key, value in following.items() if value}
        if not states:
