    return states


def exterior(left, right, cache):
    if not left:
        return (right, 1)
    if not right:
        return (left, 1)
    key = (left, right)
    if key in cache:
        return cache[key]
    merged = []
    i = 0
    j = 0
    swaps = 0
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            cache[key] = ((), 0)
            return cache[key]
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            swaps += len(left) - i
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    sign = 1
    if swaps % 2:
        sign = -1
    answer = (tuple(merged), sign)
    cache[key] = answer
    return answer


def contractions(left, right, cache):
    key = (left, right)
    if key in cache:
        return cache[key]
    p = len(left)
    q = len(right)
    subsets = [((), 0)]
    for i, mode in enumerate(left):
        if mode in right:
            delta = p - 1 - i + right.index(mode)
            subsets.extend([(chosen + (mode,), score + delta) for chosen, score in subsets])
    terms = []
    for chosen, score in subsets:
        r = len(chosen)
        exponent = (p - r) * (q - r) + score - r * (r - 1) // 2
        sign = 1
        if exponent % 2:
            sign = -1
        creation = tuple(mode for mode in right if mode not in chosen)
        annihilation = tuple(mode for mode in left if mode not in chosen)
        terms.append((creation, annihilation, sign))
    answer = tuple(terms)
    cache[key] = answer
    return answer


def atomproduct(left, right, symmetric, middlecache, wedgecache):
    lc, la = left
    rc, ra = right
    exponent = len(lc) * (len(lc) - 1) // 2 + len(la) * (len(la) - 1) // 2
    adjointsign = 1
    if exponent % 2:
        adjointsign = -1
    polynomial = {}
    for middlec, middlea, sign in contractions(lc, rc, middlecache):
        creation, csign = exterior(la, middlec, wedgecache)
        if not csign:
            continue
        annihilation, asign = exterior(middlea, ra, wedgecache)
        if not asign:
            continue
        value = adjointsign * sign * csign * asign
        groups = (creation, annihilation)
        polynomial[groups] = polynomial.get(groups, 0) + value
        if symmetric:
            transposed = (annihilation, creation)
            polynomial[transposed] = polynomial.get(transposed, 0) + value
    return {groups: value for groups, value in polynomial.items() if value}


def coordinates(left, right, diagonal):
    entries = {}
    if diagonal:
        for position, entry in enumerate(left):
            i, ci = entry
            entries[(i, i)] = ci * ci
            for later in range(position + 1, len(left)):
                j, cj = left[later]
                entries[(i, j)] = 2 * ci * cj
    else:
        for i, ci in left:
            for j, cj in right:
                if i <= j:
                    coordinate = (i, j)
                else:
                    coordinate = (j, i)
                entries[coordinate] = entries.get(coordinate, 0) + ci * cj
    return tuple((coordinate, value) for coordinate, value in entries.items() if value)


def propose(payload):
    atoms = []
    atomids = {}
    incidence = []
    normalcache = {}
    for i, word in enumerate(payload['words']):
        if word not in normalcache:
            normalcache[word] = normalform(word)
        for groups, coefficient in normalcache[word].items():
            if groups not in atomids:
                atomids[groups] = len(atoms)
                atoms.append(groups)
                incidence.append([])
            incidence[atomids[groups]].append((i, coefficient))
    middlecache = {}
    wedgecache = {}
    wordcache = {}
    result = {}
    for a, left in enumerate(atoms):
        for b in range(a, len(atoms)):
            polynomial = atomproduct(left, atoms[b], a != b, middlecache, wedgecache)
            if not polynomial:
                continue
            entries = coordinates(incidence[a], incidence[b], a == b)
            if not entries:
                continue
            for groups, coefficient in polynomial.items():
                if groups not in wordcache:
                    creation, annihilation = groups
                    wordcache[groups] = tuple((1, mode) for mode in creation) + tuple((0, mode) for mode in annihilation)
                row = result.setdefault(wordcache[groups], {})
                for coordinate, multiplier in entries:
                    row[coordinate] = row.get(coordinate, 0) + coefficient * multiplier
    answer = {}
    for word, row in result.items():
        cleaned = {coordinate: coefficient for coordinate, coefficient in row.items() if coefficient}
        if cleaned:
            answer[word] = cleaned
    return answer
